
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_c_p86vwn_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_c_p86vwn", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-7.021411781230857e-02, -6.922765994553262e-02, -6.781577266729480e-02, -6.579960162601917e-02, -6.293069721472323e-02, -5.887238853268753e-02, -5.319397005268577e-02, -4.542969088221949e-02, -3.537113291110400e-02, -2.385953745445564e-02, -1.434807538291567e-02, -4.146799884943999e-02, -4.817288492692092e-02, -3.529723597769600e-02, -1.873878424458622e-02, -1.124225842267531e-03, 5.602755802812604e-03, -5.791790613571830e-03, -2.285839838946172e-03, -3.201027765312974e-04]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


